'use strict';
/* ===== ことばの絵（絵文字が ないことばの オリジナルの絵） =====
   PICS[ことばのid] = 絵文字  または  '§キー'（下の SVG をつかう）
   SVG はすべて 100×100 のマスに かく。 */
const PK = '#4b3550';
const _st = `stroke="${PK}" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"`;
const p = (d, f = 'none') => `<path d="${d}" fill="${f}" ${_st}/>`;
const pn = (d, f) => `<path d="${d}" fill="${f}"/>`;
const ln = (d, c = PK, w = 2.5) => `<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
const r = (x, y, w, h, f, rx = 0) => `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rx}" fill="${f}" ${_st}/>`;
const rn = (x, y, w, h, f, rx = 0) => `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rx}" fill="${f}"/>`;
const c = (x, y, R, f) => `<circle cx="${x}" cy="${y}" r="${R}" fill="${f}" ${_st}/>`;
const cn = (x, y, R, f) => `<circle cx="${x}" cy="${y}" r="${R}" fill="${f}"/>`;
const e = (x, y, a, b, f, rot = 0) => `<ellipse cx="${x}" cy="${y}" rx="${a}" ry="${b}" fill="${f}" ${_st}${rot ? ` transform="rotate(${rot} ${x} ${y})"` : ''}/>`;
const en = (x, y, a, b, f, rot = 0) => `<ellipse cx="${x}" cy="${y}" rx="${a}" ry="${b}" fill="${f}"${rot ? ` transform="rotate(${rot} ${x} ${y})"` : ''}/>`;
const t = (x, y, s, txt, f = PK) => `<text x="${x}" y="${y}" font-size="${s}" font-weight="800" fill="${f}" text-anchor="middle" dominant-baseline="central" font-family="'M PLUS Rounded 1c','Hiragino Maru Gothic ProN',sans-serif">${txt}</text>`;
const em = (x, y, s, ch) => `<text x="${x}" y="${y}" font-size="${s}" text-anchor="middle" dominant-baseline="central">${ch}</text>`;
const SK = '#ffd9b8', HAIR = '#6b4226', RED = '#ff6b6b', PINK = '#ff8fab', ORG = '#ffa94d', YEL = '#ffd43b', GRN = '#69db7c', DGRN = '#2f9e44', BLU = '#74c0fc', DBLU = '#4dabf7', PUR = '#b197fc', BRN = '#c68b59', DBRN = '#8d5a3b', GRY = '#ced4da', DGRY = '#868e96', WH = '#fff';
const arrow = (x1, y1, x2, y2, col = '#ff3b6b') => { const a = Math.atan2(y2 - y1, x2 - x1), L = 7; return ln(`M${x1} ${y1} L${x2} ${y2} M${x2} ${y2} L${(x2 - L * Math.cos(a - .5)).toFixed(1)} ${(y2 - L * Math.sin(a - .5)).toFixed(1)} M${x2} ${y2} L${(x2 - L * Math.cos(a + .5)).toFixed(1)} ${(y2 - L * Math.sin(a + .5)).toFixed(1)}`, col, 3.5); };
const mark = (x, y, R = 8) => `<circle cx="${x}" cy="${y}" r="${R}" fill="rgba(255,59,107,.18)" stroke="#ff3b6b" stroke-width="3"/>${arrow(x + R + 13, y - R - 9, x + R * .8 + 1, y - R * .8 - 1)}`;
const star = (cx, cy, R) => { let d = ''; for (let k = 0; k < 10; k++) { const a = -Math.PI / 2 + k * Math.PI / 5, rr = k % 2 ? R * .45 : R; d += (k ? 'L' : 'M') + (cx + Math.cos(a) * rr).toFixed(1) + ' ' + (cy + Math.sin(a) * rr).toFixed(1); } return d + 'Z'; };

