/* ---- ひとの ポーズ ---- */
function fig(j, col = BLU) {
  const P = k => j[k].join(' ');
  return `${ln(`M${P('n')} L${P('eR')} L${P('hR')}`, SK, 6)}${ln(`M${P('h')} L${P('kR')} L${P('fR')}`, '#5c7cfa', 7)}
${ln(`M${P('n')} L${P('h')}`, col, 13)}
${ln(`M${P('h')} L${P('kL')} L${P('fL')}`, '#5c7cfa', 7)}${ln(`M${P('n')} L${P('eL')} L${P('hL')}`, SK, 6)}
${c(j.hd[0], j.hd[1], 8.5, SK)}${pn(`M${j.hd[0] - 8.5} ${j.hd[1] - 1} A8.5 8.5 0 0 1 ${j.hd[0] + 8.5} ${j.hd[1] - 1} Z`, HAIR)}`;
}
