function picSVG(key) {
  const f = PIC_SVG[key]; if (!f) return '';
  // からだ全体の絵は 少し ズームして 見やすく
  const vb = /^b_(neck|chest|stomach|hip|shoulder|elbow|wrist|knee|back)$/.test(key) ? '20 4 60 92' : '0 0 100 100';
  return `<svg viewBox="${vb}" xmlns="http://www.w3.org/2000/svg">${f()}</svg>`;
}
